import AVFoundation
import CoreMedia
import SoundAnalysis

/// Laughter detection using Apple's **built-in** sound classifier (no model to
/// download, no third-party ML). For each analysed window it reports a full
/// `LaughObservation`: the laughter confidence and which laugh class won, the
/// strongest TV-context class (for de-conflicting TV audio), a few top competing
/// classes (for debugging false positives), and the window's *real* audio timing.
///
/// We match several related laugh class identifiers (laughter, giggle, chuckle …)
/// so we don't overfit to a single style of laugh.
final class LaughDetector: NSObject, SNResultsObserving {
    private var analyzer: SNAudioStreamAnalyzer?
    private let queue = DispatchQueue(label: "com.laughcounter.sound-analysis")

    /// Called with a full observation for each analysed window.
    var onObservation: ((LaughObservation) -> Void)?

    // Stems, not whole words: the classifier emits gerunds like "giggling", so
    // "giggle" would miss it — "giggl" matches both "giggle" and "giggling".
    private static let laughKeywords = ["laugh", "giggl", "chuckl", "chortl",
                                        "snicker", "cackl", "guffaw"]
    // "Produced-audio" classes that point at a TV / recording rather than a person
    // in the room: a soundtrack (music, instruments), dialogue (speech, chatter),
    // and a broadcast audience (crowd, applause, cheering). Matched as
    // case-insensitive substrings, so "guitar"/"electric_guitar" both hit "guitar".
    // The strongest of these becomes the episode's `tvSignal` for you-vs-TV attribution.
    private static let tvKeywords = [
        "applause", "crowd", "cheer", "audience", "television", "clapping",
        "music", "speech", "chatter", "singing", "orchestra",
        "drum", "percussion", "instrument", "guitar", "piano", "violin",
        "string", "bassoon", "flute", "trumpet", "didgeridoo", "saxophone",
    ]

    // The analyzer wants monotonically increasing frame positions starting near 0.
    // We anchor those positions (and the wall-clock epoch) to the first buffer of
    // each stream, so window timestamps are real audio times, valid across restarts.
    private var baseSampleTime: AVAudioFramePosition?
    private var startEpoch: Double = 0

    // One log line per stream confirming the analysis pipeline is delivering
    // results after a (re)start — so "it stopped detecting" is diagnosable.
    private var sawFirstResult = false

    func configure(format: AVAudioFormat) throws {
        let analyzer = SNAudioStreamAnalyzer(format: format)
        let request = try SNClassifySoundRequest(classifierIdentifier: .version1)
        try analyzer.add(request, withObserver: self)
        self.analyzer = analyzer
        self.baseSampleTime = nil
    }

    func analyze(_ buffer: AVAudioPCMBuffer, at when: AVAudioTime) {
        queue.async { [weak self] in
            guard let self = self, let analyzer = self.analyzer else { return }
            if self.baseSampleTime == nil {
                self.baseSampleTime = when.sampleTime
                self.startEpoch = Date().timeIntervalSince1970
            }
            let base = self.baseSampleTime ?? when.sampleTime
            analyzer.analyze(buffer, atAudioFramePosition: when.sampleTime - base)
        }
    }

    /// Forget the stream anchor so the next buffer re-anchors timing. Call when
    /// (re)starting the audio stream.
    func reset() {
        queue.async { [weak self] in
            self?.baseSampleTime = nil
            self?.sawFirstResult = false
        }
    }

    // MARK: SNResultsObserving

    func request(_ request: SNRequest, didProduce result: SNResult) {
        guard let classification = result as? SNClassificationResult else { return }

        var laughScore = 0.0, laughType = ""
        var tvScore = 0.0, tvLabel = ""
        var nonLaugh: [ContextScore] = []
        for c in classification.classifications {
            let id = c.identifier.lowercased()
            let conf = c.confidence
            if Self.laughKeywords.contains(where: { id.contains($0) }) {
                if conf > laughScore { laughScore = conf; laughType = c.identifier }
            } else {
                nonLaugh.append(ContextScore(label: c.identifier, confidence: conf))
                if Self.tvKeywords.contains(where: { id.contains($0) }), conf > tvScore {
                    tvScore = conf; tvLabel = c.identifier
                }
            }
        }
        let topContext = Array(nonLaugh.sorted { $0.confidence > $1.confidence }.prefix(3))

        let windowStart = CMTimeGetSeconds(classification.timeRange.start)
        var windowDur = CMTimeGetSeconds(classification.timeRange.duration)
        if !windowDur.isFinite || windowDur <= 0 { windowDur = 0.5 }
        let epoch = startEpoch + (windowStart.isFinite ? windowStart : 0)

        if !sawFirstResult {
            sawFirstResult = true
            AppLog.shared.log("first analysis result received")
        }

        onObservation?(LaughObservation(
            time: epoch, windowDuration: windowDur,
            laughScore: laughScore, laughType: laughType,
            contextScore: tvScore, contextLabel: tvLabel,
            context: topContext))
    }

    func request(_ request: SNRequest, didFailWithError error: Error) {
        AppLog.shared.log("sound analysis failed: \(error.localizedDescription)", level: "ERROR")
    }
}
import AppKit
import Foundation

/// Appends laugh events to a JSONL log under
/// `~/Library/Application Support/LaughCounter/laughs.jsonl`.
///
/// Deliberately greppable. Fields are written in a **fixed
/// order** every line (`start_iso, label, start, end, peak, duration, mean,
/// source`, then `type`/`context` when present) so the log diffs cleanly and is
/// easy to eyeball — `JSONSerialization` can't guarantee key order, so we render
/// the JSON ourselves. Confidence values are rounded (they carry no meaning past a
/// couple of decimals). No audio is stored — only metadata.
final class LaughStore {
    private let directory: URL
    let fileURL: URL

    init() {
        let base = FileManager.default.urls(for: .applicationSupportDirectory,
                                            in: .userDomainMask)[0]
        directory = base.appendingPathComponent("LaughCounter", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory,
                                                 withIntermediateDirectories: true)
        fileURL = directory.appendingPathComponent("laughs.jsonl")
    }

    /// Log a detected laugh.
    func append(_ event: LaughEvent, source: String = "mic", label: String = "auto") {
        var fields: [(String, JSON)] = [
            ("start_iso", .str(Self.iso(event.start))),
            ("label", .str(label)),
            ("start", .num(round3(event.start))),
            ("end", .num(round3(event.end))),
            ("peak", .num(round2(event.peak))),
            ("duration", .num(round2(event.duration))),
            ("mean", .num(round2(event.mean))),
            ("source", .str(source)),
            ("origin", .str(event.origin)),
            ("tv_signal", .num(round2(event.tvSignal))),
            ("origin_reason", .str(event.originReason)),
        ]
        if !event.type.isEmpty {
            fields.append(("type", .str(event.type)))
        }
        if !event.context.isEmpty {
            fields.append(("context", .arr(event.context.map { c in
                JSON.obj([("label", .str(c.label)), ("confidence", .num(round2(c.confidence)))])
            })))
        }
        write(JSON.obj(fields))
    }

    /// Log a laugh you told us we missed. `source` distinguishes the spoken
    /// command (`"voice"`) from a menu/keyboard click (`"button"`).
    func appendMissed(source: String = "voice") {
        let now = Date().timeIntervalSince1970
        // A miss you reported is, by definition, you.
        append(LaughEvent(start: now - 0.5, end: now, duration: 0.5,
                          peak: 0, mean: 0, type: "", context: [],
                          origin: "me", originReason: "you reported it", tvSignal: 0),
               source: source, label: "missed")
    }

    /// Count today's counted laughs (excludes candidates/rejects). Pass `origin`
    /// ("me" or "tv") to count just that bucket; omit for the total.
    func todayCount(origin: String? = nil) -> Int {
        guard let content = try? String(contentsOf: fileURL, encoding: .utf8) else { return 0 }
        let calendar = Calendar.current
        var count = 0
        for line in content.split(separator: "\n") {
            guard let data = line.data(using: .utf8),
                  let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let start = obj["start"] as? Double else { continue }
            // Candidates (sub-threshold, logged for alignment) and rejects don't count.
            if let label = obj["label"] as? String, label == "rejected" || label == "candidate" {
                continue
            }
            // Older entries predate attribution; treat a missing origin as "me".
            if let origin = origin, (obj["origin"] as? String ?? "me") != origin {
                continue
            }
            if calendar.isDateInToday(Date(timeIntervalSince1970: start)) { count += 1 }
        }
        return count
    }

    func revealInFinder() {
        NSWorkspace.shared.activateFileViewerSelecting([fileURL])
    }

    // MARK: - JSON with guaranteed field order

    private func write(_ json: JSON) {
        let line = json.encoded() + "\n"
        guard let bytes = line.data(using: .utf8) else { return }
        if let handle = try? FileHandle(forWritingTo: fileURL) {
            defer { try? handle.close() }
            handle.seekToEndOfFile()
            handle.write(bytes)
        } else {
            try? bytes.write(to: fileURL)
        }
    }

    private static func iso(_ epoch: Double) -> String {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime]
        return f.string(from: Date(timeIntervalSince1970: epoch))
    }
}

private func round2(_ x: Double) -> Double { (x * 100).rounded() / 100 }
private func round3(_ x: Double) -> Double { (x * 1000).rounded() / 1000 }

/// A minimal ordered-JSON value, so object keys serialise in insertion order
/// (unlike `[String: Any]` + `JSONSerialization`).
private indirect enum JSON {
    case str(String)
    case num(Double)
    case obj([(String, JSON)])
    case arr([JSON])

    func encoded() -> String {
        switch self {
        case .str(let s): return JSON.encodeString(s)
        case .num(let d): return JSON.encodeNumber(d)
        case .obj(let pairs):
            return "{" + pairs.map { "\(JSON.encodeString($0.0)):\($0.1.encoded())" }
                .joined(separator: ",") + "}"
        case .arr(let items):
            return "[" + items.map { $0.encoded() }.joined(separator: ",") + "]"
        }
    }

    private static func encodeNumber(_ d: Double) -> String {
        guard d.isFinite else { return "0" }
        // Whole numbers as integers (0 not 0.0); Swift's String(Double) already
        // gives the shortest round-trippable form for the rest (0.63, not 0.6300…).
        if d == d.rounded() && abs(d) < 1e15 { return String(Int64(d)) }
        return String(d)
    }

    private static func encodeString(_ s: String) -> String {
        var out = "\""
        for scalar in s.unicodeScalars {
            switch scalar {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            default:
                if scalar.value < 0x20 {
                    out += String(format: "\\u%04x", scalar.value)
                } else {
                    out.unicodeScalars.append(scalar)
                }
            }
        }
        return out + "\""
    }
}

import Foundation

/// A competing (non-laugh) sound class and its confidence, kept for TV
/// de-confliction and false-positive debugging.
struct ContextScore {
    let label: String
    let confidence: Double
}

/// One episode of detected laughter (not a single frame — a whole laugh).
struct LaughEvent {
    let start: Double   // epoch seconds
    let end: Double
    let duration: Double
    let peak: Double
    let mean: Double
    let type: String            // which laugh class dominated ("" if unknown)
    let context: [ContextScore] // top non-laugh classes heard during the episode
    let origin: String          // hypothesis about the source: "me" | "tv"
    let originReason: String    // human-readable why, for the activity log
    let tvSignal: Double        // strongest produced-audio context confidence (0…1)
}

/// One analysed window handed to the counter. Carries the *real* audio timing
/// (from `SNClassificationResult.timeRange`) plus the winning laugh class and the
/// strongest TV-context class, so durations are accurate and TV audio can be told
/// apart from a person laughing in the room.
struct LaughObservation {
    let time: Double            // epoch seconds of the window start (real audio time)
    let windowDuration: Double  // real window length from SoundAnalysis
    let laughScore: Double      // max confidence across laugh classes
    let laughType: String       // which laugh class won ("" if none)
    let contextScore: Double    // max confidence across TV-context classes
    let contextLabel: String    // which TV-context class was strongest
    let context: [ContextScore] // a few top non-laugh classes (for logging)
}

/// Turns a stream of per-window observations into discrete laughs, using a
/// hysteresis state machine:
///
/// * start tracking when confidence rises to `enterThreshold`,
/// * keep going while it stays above the lower `exitThreshold` (hysteresis),
/// * bridge silences shorter than `mergeGap` (a fit of giggles = one laugh),
/// * only record episodes lasting at least `minDuration`.
///
/// An episode is **counted** as a real laugh only if its peak confidence reaches
/// `countThreshold`. Episodes that clear the lower `enterThreshold` but not
/// `countThreshold` are emitted as **candidates** (`onCandidate`) — logged for
/// later analysis / threshold tuning, but not counted.
///
/// Episode length comes from the observations' real window bounds, so a laugh
/// that spans several windows reports its true duration instead of a fixed 0.5s.
/// Deterministic and I/O-free.
final class LaughCounter {
    /// Peak confidence an episode must reach to be *counted* as a real laugh.
    var countThreshold = 0.5
    /// Lower bar at which we start tracking an episode at all. Deliberately low so
    /// near-misses are logged as candidates too — later "I laughed" feedback can be
    /// aligned against a nearby low-confidence event instead of nothing.
    var enterThreshold = 0.15
    /// Hysteresis exit — an open episode stays open while confidence holds above this.
    var exitThreshold = 0.1
    var minDuration = 0.4
    // Bridge gaps up to this long so one laugh spanning several analysis windows
    // is one episode, not several. The built-in classifier emits ~3s windows
    // every ~1.5s, so this must exceed that hop or every overlapping window
    // becomes its own (duplicate) laugh with a fixed ~3s duration.
    var mergeGap = 2.0
    var frameSeconds = 0.5   // fallback window length if the API doesn't supply one

    /// Emit sub-threshold episodes (peak below `countThreshold`) via `onCandidate`.
    var logCandidates = true

    /// You-vs-TV attribution: if the strongest "produced-audio" context class
    /// (music / speech / audience / instruments) reaches this confidence, the
    /// episode is hypothesised to come from the TV rather than a person in the
    /// room. A guess, not a verdict — laughs are still logged, just attributed.
    var tvThreshold = 0.3

    /// Called (on the caller's thread) when a counted laugh is finalised. The
    /// event's `origin` carries the you-vs-TV hypothesis.
    var onLaugh: ((LaughEvent) -> Void)?
    /// Called for a sub-threshold episode (peak < `countThreshold`) — logged for
    /// alignment/tuning, not counted. Also carries an `origin` hypothesis.
    var onCandidate: ((LaughEvent) -> Void)?

    private var start: Double?
    private var lastActive = 0.0
    private var lastWindow = 0.5
    private var peak = 0.0
    private var sum = 0.0
    private var n = 0
    private var peakType = ""
    private var peakContext = 0.0
    private var peakContextLabel = ""
    private var contextAgg: [String: Double] = [:]
    private var lastTs: Double?

    func update(_ obs: LaughObservation) {
        if let last = lastTs, obs.time < last { return }  // ignore backward time
        lastTs = obs.time

        let loud = obs.laughScore >= enterThreshold
        let soft = obs.laughScore >= exitThreshold

        // Close a stale episode first, regardless of this window's loudness, so a
        // laugh resuming after a > mergeGap silence is a new laugh, not a merge.
        if start != nil && obs.time - lastActive > mergeGap {
            finalizeEpisode()
        }

        if start == nil {
            if loud { begin(obs) }
        } else if soft {
            extend(obs)
        }
    }

    /// Finalise any episode still open (e.g. on shutdown or before a pause).
    func flush() {
        if start != nil { finalizeEpisode() }
    }

    /// Drop all state, including the stream clock — call when (re)starting the
    /// audio stream so the new stream's timestamps aren't rejected as "backward".
    func reset() {
        resetEpisode()
        lastTs = nil
    }

    private func begin(_ o: LaughObservation) {
        start = o.time; lastActive = o.time; lastWindow = o.windowDuration
        peak = o.laughScore; sum = o.laughScore; n = 1; peakType = o.laughType
        peakContext = o.contextScore; peakContextLabel = o.contextLabel
        contextAgg = [:]; accumulateContext(o)
    }

    private func extend(_ o: LaughObservation) {
        lastActive = o.time; lastWindow = o.windowDuration
        if o.laughScore > peak { peak = o.laughScore; peakType = o.laughType }
        sum += o.laughScore; n += 1
        if o.contextScore > peakContext { peakContext = o.contextScore; peakContextLabel = o.contextLabel }
        accumulateContext(o)
    }

    private func accumulateContext(_ o: LaughObservation) {
        for c in o.context {
            contextAgg[c.label] = max(contextAgg[c.label] ?? 0, c.confidence)
        }
    }

    private func finalizeEpisode() {
        guard let s = start else { return }
        let end = lastActive + (lastWindow > 0 ? lastWindow : frameSeconds)
        let duration = end - s
        let capPeak = peak
        let capMean = n > 0 ? sum / Double(n) : 0
        let capType = peakType
        let tvSignal = peakContext
        let tvLabel = peakContextLabel
        let ctx = contextAgg.sorted { $0.value > $1.value }.prefix(3)
            .map { ContextScore(label: $0.key, confidence: $0.value) }
        resetEpisode()

        guard duration >= minDuration else { return }

        // You-vs-TV hypothesis: a strong produced-audio context (soundtrack,
        // dialogue, audience, instruments) points at the TV; clean laughter with
        // little of that points at a person in the room.
        let origin: String
        let reason: String
        if tvSignal >= tvThreshold {
            origin = "tv"
            reason = String(format: "%@=%.2f (soundtrack/audience) → TV",
                            tvLabel.isEmpty ? "produced-audio" : tvLabel, tvSignal)
        } else {
            origin = "me"
            reason = String(format: "clean laughter, tv-context %.2f → you", tvSignal)
        }

        let event = LaughEvent(start: s, end: end, duration: duration,
                               peak: capPeak, mean: capMean, type: capType,
                               context: ctx, origin: origin,
                               originReason: reason, tvSignal: tvSignal)
        if capPeak < countThreshold {
            if logCandidates { onCandidate?(event) }
        } else {
            onLaugh?(event)
        }
    }

    private func resetEpisode() {
        start = nil; lastActive = 0; lastWindow = frameSeconds
        peak = 0; sum = 0; n = 0; peakType = ""
        peakContext = 0; peakContextLabel = ""; contextAgg = [:]
    }
}

// "Never build an `AVAudioEngine` to ask whether a microphone exists" (#88), as
// a check: `AVAudioEngine` may only be constructed in `AudioHub`.
